def run(*args: str) -> str:
    result = subprocess.run(
        args,
        check=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    return result.stdout.strip()


def fail(message: str) -> None:
    raise SystemExit(f"STAGE74_PRECHECK_FAILED: {message}")


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        fail(f"{label}: expected exactly one anchor, found {count}")
    return text.replace(old, new, 1)


def insert_before_once(text: str, anchor: str, addition: str, label: str) -> str:
    count = text.count(anchor)
    if count != 1:
        fail(f"{label}: expected exactly one anchor, found {count}")
    return text.replace(anchor, addition + anchor, 1)


def replace_nth(text: str, old: str, new: str, occurrence: int, label: str) -> str:
    starts = []
    pos = 0
    while True:
        idx = text.find(old, pos)
        if idx < 0:
            break
        starts.append(idx)
        pos = idx + len(old)
    if len(starts) < occurrence:
        fail(f"{label}: occurrence {occurrence} missing; found {len(starts)}")
    idx = starts[occurrence - 1]
    return text[:idx] + new + text[idx + len(old):]


def slice_replace(text: str, start: str, end: str, replacement: str, label: str) -> str:
    if text.count(start) != 1 or text.count(end) != 1:
        fail(f"{label}: range anchors are not unique")
    a = text.index(start)
    b = text.index(end, a)
    return text[:a] + replacement + "\n\n" + text[b:]


def atomic_write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_name = tempfile.mkstemp(prefix=path.name + ".", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_name, path)
    finally:
        if os.path.exists(tmp_name):
            os.unlink(tmp_name)


